          contentBengali: `যে ব্যক্তি এই বিধির অধীন যাবজ্জীবন কারাদণ্ডে বা অন্য কোনো কারাদণ্ডে দণ্ডনীয় কোনো অপরাধ সংঘটনের উদ্যোগ গ্রহণ করে এবং সেই অপরাধ সংঘটনের উদ্দেশ্যে কোনো কার্য সম্পাদন করে, অথচ যে ক্ষেত্রে এইরূপ উদ্যোগের শাস্তির জন্য কোনো সুনির্দিষ্ট বিধান এই বিধিতে নাই, সে উক্ত অপরাধের জন্য নির্ধারিত সর্বোচ্চ কারাদণ্ডের মেয়াদের অর্ধেকের (১/২) অনধিক যেকোনো বর্ণনার কারাদণ্ডে, অথবা অর্থদণ্ডে, অথবা উভয় দণ্ডেই দণ্ডিত হইবে।`,
